"""Ask Cerebras what this key can see, through the one door. Prints no key.

A 403 is either "this key is rejected" or "this key cannot have that model", and
the two have different owners: one is a secret to rotate, the other an
entitlement to request. `harvesting/preflight.py` refuses a model substitution,
so knowing which is the whole question.

The key is `.strip()`ed in `pipeline.synth_generate.backend_from_env` for the
same reason the generator needs it: a secret stored with a trailing newline
yields an Authorization header the API rejects with 403, which is
indistinguishable from a revoked key unless you look for it. Needs
`PYTHONPATH=training`.
"""
from __future__ import annotations

import json
import os
import sys
import urllib.error
import urllib.request

from pipeline.backends import BackendError
from pipeline.synth_generate import CEREBRAS_BASE_URL, MODEL, backend_from_env


def main() -> int:
    raw = os.environ.get("CEREBRAS_API_KEY", "")
    key = raw.strip()
    backend = backend_from_env()
    if backend is None:
        print("CEREBRAS_API_KEY is not set in this job", file=sys.stderr)
        return 2
    # Shape only, never the value: length, prefix, and whether it arrived with
    # surrounding whitespace, which is the failure this exists to report.
    print("key: %d chars (%d before strip), prefix %r, stripped_whitespace=%s"
          % (len(key), len(raw), key[:4], raw != key))

    req = urllib.request.Request(CEREBRAS_BASE_URL + "/models",
                                 headers={"Authorization": "Bearer " + key})
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            listing = json.loads(resp.read().decode("utf-8"))
    except urllib.error.HTTPError as exc:
        print("GET /models failed: HTTP %d" % exc.code, file=sys.stderr)
        if exc.code in (401, 403):
            print("401/403 on the listing means the key itself is rejected: rotate "
                  "the CEREBRAS_API_KEY secret. It is not a model entitlement.",
                  file=sys.stderr)
        return 1
    except (urllib.error.URLError, OSError, ValueError) as exc:
        print("GET /models failed: %s" % type(exc).__name__, file=sys.stderr)
        return 1
    ids = sorted(str(m.get("id", "")) for m in (listing.get("data") or []) if isinstance(m, dict))
    print("models visible to this key (%d):" % len(ids))
    for i in ids:
        print("  %s%s" % (i, "   <-- the pinned one" if i == MODEL else ""))
    if MODEL not in ids:
        print("\n%s is NOT visible. harvesting/preflight.py refuses a substitution "
              "and so does this: a bank generated by a different model is a "
              "different bank." % MODEL, file=sys.stderr)
        return 1

    # One real completion, because a visible model can still be unentitled.
    # `reasoning_effort="none"` is required, not tidy: with reasoning on, this
    # model answers in a separate channel and leaves `content` empty, so the
    # call succeeds and returns nothing.
    try:
        out = backend.complete([{"role": "user", "content": "Reply with the single word: ready"}],
                               max_tokens=64, temperature=0.0, reasoning_effort="none")
    except BackendError as exc:
        # The message may quote the response body; the status is what matters.
        print("chat/completions failed: %s" % str(exc).split(":")[0], file=sys.stderr)
        return 1
    reply = out.text.strip()
    print("completion content: %r" % reply[:60])
    if not reply:
        print("the call succeeded and returned no content: the reasoning "
              "contract is wrong, not the key", file=sys.stderr)
        return 1
    return 0


if __name__ == "__main__":
    sys.exit(main())
